// The page books-list: Books. It lists books through listBooks, a page
// at a time, and runs withdrawBook on a row.

import {
  on, emit,
  BOOKS_LIST_FILTERED, BOOKS_LIST_PAGED, BOOKS_LIST_LOADED, BOOKS_LIST_FAILED,
  WITHDRAW_BOOK_SUCCEEDED, WITHDRAW_BOOK_FAILED,
} from "./events.js";
import { arrived, go, href } from "./pages.js";
import { ask } from "./ask.js";
import { call, property } from "./service.js";

// The operation the list reads.
const source = { operation: "listBooks", method: "GET", path: "/books" };

const columns = ["title", "shelf"];
const pageSize = 25;

const messages = {
  empty: "The catalogue is empty.",
  filteredEmpty: "No book is on this shelf.",
  failed: "This cannot be done right now. Try again in a moment.",
};

// What each operation's refusals say, by status: the page's failed states.
const refusals = {
  listBooks: {},
  withdrawBook: {
    "409": "A member holds this book, so it stays in the catalogue.",
  },
};

const actions = [
  {
    label: "Withdraw",
    operation: "withdrawBook",
    method: "POST",
    path: "/books/{bookId}/withdraw",
    parameters: (row) => ({ bookId: row.id }),
    message: "The book is withdrawn.",
    succeeded: WITHDRAW_BOOK_SUCCEEDED,
    failed: WITHDRAW_BOOK_FAILED,
  },
];

/** The message of a refusal of an operation, or the page's default. */
function refusal(operation, status) {
  return refusals[operation][String(status)] ?? messages.failed;
}

/** Reads the list: the filters given, then the page. Only the answer to
    the latest request counts, and a page becomes the list's page once it
    has arrived. */
function loader() {
  let filters = {};
  let page = 1;
  let latest = 0;
  async function load(wanted) {
    const asked = ++latest;
    const query = new URLSearchParams();
    for (const [name, value] of Object.entries(filters)) {
      if (value !== "") {
        query.set(name, value);
      }
    }
    const filtered = [...query.keys()].length > 0;
    query.set("page", String(wanted));
    query.set("pageSize", String(pageSize));
    try {
      const response = await call(source, { query: Object.fromEntries(query), list: source.list });
      if (asked !== latest) {
        return;
      }
      if (!response.ok) {
        emit(BOOKS_LIST_FAILED, { status: response.status });
        return;
      }
      const body = await response.json();
      if (asked !== latest) {
        return;
      }
      const items = property(body, "items");
      const totalPages = property(body, "totalPages");
      if (items.length === 0 && wanted > 1 && totalPages > 0 && wanted > totalPages) {
        load(totalPages); // the page asked for is past the last
        return;
      }
      page = wanted;
      emit(BOOKS_LIST_LOADED, { items, totalItems: property(body, "totalItems"), totalPages, page, filtered });
    } catch {
      if (asked === latest) {
        emit(BOOKS_LIST_FAILED, { status: 0 });
      }
    }
  }
  on(BOOKS_LIST_FILTERED, (payload) => {
    filters = payload;
    load(1);
  });
  on(BOOKS_LIST_PAGED, (payload) => load(payload.page));
  for (const action of actions) {
    on(action.succeeded, () => load(page));
  }
  load(1);
}

/** The filters form. */
function filterForm() {
  const form = document.getElementById("filters");
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    const given = [...new FormData(form)].map(([name, value]) => [name, String(value).trim()]);
    emit(BOOKS_LIST_FILTERED, Object.fromEntries(given));
  });
}

/** Runs an action on a row once the person confirms it and gives the
    reason it asks for, its button disabled while it runs; an action that
    leads to another page opens it once it has succeeded. */
async function run(action, row, button) {
  const reason = await ask(action.confirm, action.reason);
  if (reason === null) {
    return;
  }
  const given = { parameters: action.parameters(row) };
  if (action.reason) {
    given.body = { [action.reason.name]: reason };
  }
  button.disabled = true;
  try {
    const response = await call(action, given);
    if (response.ok) {
      emit(action.succeeded, { id: row.id });
      if (action.navigate) {
        go(action.navigate.page, action.navigate.with(row), action.message);
      }
    } else {
      button.disabled = false;
      emit(action.failed, { id: row.id, status: response.status });
    }
  } catch {
    button.disabled = false;
    emit(action.failed, { id: row.id, status: 0 });
  }
}

/** The table of books. Focus in it stays on the same control, or moves
    to the table when its row is gone. */
function table() {
  const body = document.querySelector("#rows tbody");
  const head = document.querySelectorAll("#rows thead th");
  on(BOOKS_LIST_LOADED, ({ items }) => {
    const focused = body.contains(document.activeElement) ? document.activeElement.dataset.key : undefined;
    body.replaceChildren();
    for (const row of items) {
      const tr = document.createElement("tr");
      columns.forEach((name, i) => {
        const td = document.createElement("td");
        td.className = head[i].className;
        td.textContent = row[name] ?? "";
        tr.append(td);
      });
      const cell = document.createElement("td");
      for (const action of actions) {
        if (action.when && !action.when(row)) {
          continue;
        }
        const label = `${action.label} ${row[columns[0]] ?? ""}`.trim();
        if (action.page) {
          const link = document.createElement("a");
          link.href = href(action.page, action.with(row));
          link.textContent = action.label;
          link.setAttribute("aria-label", label);
          link.dataset.key = `${action.page} ${row.id}`;
          cell.append(link);
          continue;
        }
        const button = document.createElement("button");
        button.type = "button";
        button.textContent = action.label;
        button.setAttribute("aria-label", label);
        button.dataset.key = `${action.operation} ${row.id}`;
        button.addEventListener("click", () => run(action, row, button));
        cell.append(button);
      }
      tr.append(cell);
      body.append(tr);
    }
    if (focused !== undefined) {
      const again = [...body.querySelectorAll("a, button")].find((control) => control.dataset.key === focused);
      (again ?? document.getElementById("rows")).focus();
    }
  });
}

/** The status line: states and the messages of events, announced without
    moving focus, the message the page that opened this one left first. */
function statusLine() {
  const line = document.getElementById("status");
  // An event's message stays until the person filters or pages; a state
  // gives way to the list it describes.
  let kept = false;
  function show(text, failed, keep) {
    line.textContent = text;
    line.classList.toggle("failed", failed);
    kept = keep;
  }
  on(BOOKS_LIST_FILTERED, () => show("", false, false));
  on(BOOKS_LIST_PAGED, () => show("", false, false));
  on(BOOKS_LIST_LOADED, ({ items, filtered }) => {
    if (kept) {
      return;
    }
    show(items.length === 0 ? (filtered ? messages.filteredEmpty : messages.empty) : "", false, false);
  });
  on(BOOKS_LIST_FAILED, ({ status }) => show(refusal("listBooks", status), true, false));
  for (const action of actions) {
    on(action.succeeded, () => show(action.message, false, true));
    on(action.failed, ({ status }) => show(refusal(action.operation, status), true, true));
  }
  const carried = arrived();
  show(carried, false, carried !== "");
}

/** The pager. A button that is disabled while it has focus hands focus on. */
function pager() {
  const nav = document.getElementById("pager");
  const where = nav.querySelector("span");
  const [previous, next] = nav.querySelectorAll("button");
  let page = 1;
  on(BOOKS_LIST_LOADED, (payload) => {
    page = payload.page;
    where.textContent = `Page ${payload.page} of ${Math.max(payload.totalPages, 1)}`;
    const focused = document.activeElement;
    previous.disabled = payload.page <= 1;
    next.disabled = payload.page >= payload.totalPages;
    if (focused instanceof HTMLButtonElement && nav.contains(focused) && focused.disabled) {
      const other = focused === previous ? next : previous;
      (other.disabled ? document.getElementById("rows") : other).focus();
    }
  });
  for (const button of [previous, next]) {
    button.addEventListener("click", () => emit(BOOKS_LIST_PAGED, { page: page + Number(button.dataset.step) }));
  }
}

filterForm();
table();
statusLine();
pager();
loader();
